import{z as s,x as o,o as A,c as d,q as r,j as t,D as e,d as a,s as i,S as l,b as B}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"强化学习执行的深入","description":"","frontmatter":{"title":"强化学习执行的深入","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/dp-rl-execution-deep.md","filePath":"quant/dp-rl-execution-deep.md","lastUpdated":1791413859000}'),p={name:"quant/dp-rl-execution-deep.md"};function F(u,E,C,D,m,h){const n=o("Mermaid");return A(),d("div",null,[E[2]||(E[2]=r('<h1 id="强化学习执行的深入" tabindex="-1">强化学习执行的深入 <a class="header-anchor" href="#强化学习执行的深入" aria-label="Permalink to &quot;强化学习执行的深入&quot;">​</a></h1><div class="epigraph"><p>执行的基准从来不是「赚最多」，而是同一落地风险下少付成本；强化学习在这里替换的不是交易员，是线性二次假设本身。</p><footer>—— 据 Nevmyvaka, Feng and Kearns, ICML, 2006；Dabérius, Granat and Pakkanen, Quantitative Finance, 2020 整理</footer></div><p><a href="/quant/dp-deep-micro-signals">上一课</a>把微观结构信号的成本口径钉住：信号值多少，要扣掉冲击之后才算。本课把信号换成动作：执行是微观结构里第一个正面回答「我的订单会改变环境」的控制问题。<a href="/quant/almgren-chriss">Almgren–Chriss</a> 在线性冲击与二次风险的世界里给出最优切片；<a href="/quant/rl-execution">强化学习执行</a>早已把这个问题搬进马尔可夫决策过程；报价侧的竞争版本见<a href="/quant/rl-market-making">强化学习做市</a>。本课做深化：状态与动作怎么设计、环境从哪来、策略必须与哪些解析基线对照才算数。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>线性二次框架的三条假设在真实簿上都绷得紧：冲击是临时加永久两项、线性于成交速率；市场参数静态已知；订单只有连续量。真实执行面对的是：冲击依赖簿密度与价差状态（上一课的条件化口径）、限价与市价是离散且带成交概率的选择、剩余时间是硬约束、对手算法在适应。强化学习换掉的是「策略空间受解析形式约束」这一条——代价是把模型假设从方程挪进环境：环境怎么造，策略的上限就在哪。金融没有可交互的物理环境：历史回放不响应你的订单，生成仿真引入设定误差，在线试错在真金白银上不可行。这是执行 RL 与游戏 RL 的根本差别，也是方法选择的出发点。</p><p><span class="marginnote">「环境决定策略上限」可以类比飞行模拟器：学员学不会侧风降落，是因为模拟器里根本没有侧风。执行 RL 同理——历史回放不响应你的大单，策略就永远学不出冲击规避；环境里缺什么，策略就缺什么能力，这与网络大小无关。</span></p><h3 id="状态、动作与奖励的设计" tabindex="-1">状态、动作与奖励的设计 <a class="header-anchor" href="#状态、动作与奖励的设计" aria-label="Permalink to &quot;状态、动作与奖励的设计&quot;">​</a></h3><p>状态收进：库存、剩余时间、价差与深度、近期订单流失衡、已付冲击；动作是子单的类型、价格层级与数量；奖励用相对<a href="/quant/arrival-price">到达价</a>的实现短缺，加终期未清库存的重罚——让拖到最后市价清算的代价显式化。奖励塑形改变问题本身：把成交概率加进奖励，策略会学出挑软柿子成交的伪影；延迟到期的信用分配见<a href="/quant/delayed-reward-trading">延迟奖励</a>。</p><p><span class="marginnote">Nevmyvaka、Feng 与 Kearns 2006 的训练环境是历史 TAQ 回放，比较的是相对基准的执行改进，不是绝对盈利；环境里没有自己冲击的位置，结论只覆盖限价放置这一小步动作。环境登记从此是执行 RL 交付物的一部分。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>环境三条路：历史回放最保守、零冲击反事实，适合限价放置这类小额动作；解析冲击模型（<a href="/quant/obizhaeva-wang">Obizhaeva–Wang</a> 型暂态加永久冲击）可控可解释，检验策略对冲击形态的敏感度；撮合仿真（<a href="/quant/abides-simulation">ABIDES</a> 一类事件级环境）最真实也最贵。训练用离线方法——拟合 Q 或带约束的策略学习——因为在线探索不可行；对环境的每一处简化都要登记，交付时随策略冻结，<a href="/quant/sim-to-real-trading">仿真到实盘</a>的缝不是稳健性检查，是验收项。对照协议：同一数据、同一约束下与 TWAP/VWAP、Almgren–Chriss 切片及朴素分批同台，报实现短缺的分布而不只均值——RL 的优势若只在尾部情景，均值对照会抹掉它。</p>',11)),(A(),t(l,null,{default:e(()=>[i(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20ST%5B%22%E7%8A%B6%E6%80%81%EF%BC%9A%E5%BA%93%E5%AD%98%2F%E6%97%B6%E9%99%90%2F%E7%B0%BF%E7%89%B9%E5%BE%81%22%5D%20--%3E%20POL%5B%22%E7%A6%BB%E7%BA%BF%E7%AD%96%E7%95%A5%20%CF%80_%CE%B8%22%5D%0A%20%20POL%20--%3E%20ACT%5B%22%E5%AD%90%E5%8D%95%EF%BC%9A%E7%B1%BB%E5%9E%8B%2F%E4%BB%B7%E6%A0%BC%2F%E9%87%8F%22%5D%0A%20%20ACT%20--%3E%20ENV%5B%22%E5%9B%9E%E6%94%BE%E6%88%96%E5%86%B2%E5%87%BB%E4%BB%BF%E7%9C%9F%22%5D%0A%20%20ENV%20--%3E%20FILL%5B%22%E6%88%90%E4%BA%A4%E4%B8%8E%E5%86%B2%E5%87%BB%E5%9B%9E%E6%8A%A5%22%5D%0A%20%20FILL%20--%3E%20RW%5B%22%E5%A5%96%E5%8A%B1%EF%BC%9A%E7%9F%AD%E7%BC%BA%20%2B%20%E7%BB%88%E6%9C%9F%E9%87%8D%E7%BD%9A%22%5D%0A%20%20RW%20--%3E%20POL%0A%20%20BASE%5B%22TWAP%20%2F%20VWAP%20%2F%20AC%20%E5%9F%BA%E7%BA%BF%22%5D%20--%3E%20EVAL%5B%22%E5%90%8C%E6%95%B0%E6%8D%AE%E5%90%8C%E7%BA%A6%E6%9D%9F%E5%AF%B9%E7%85%A7%22%5D%0A%20%20ENV%20--%3E%20EVAL%0A%20%20EVAL%20--%3E%20POL%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B("h2",{id:"机制",tabindex:"-1"},[a("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=B("p",null,[a("学出的策略要能被存货逻辑解读：无交易区（价差贵、时限宽时不动）、限价与市价的切换随紧急度移动、临终加速清算。这些与解析解的定性一致，是「学对了问题」的证据。反过来，若策略的收益集中在回放器的人造可预测性上——比如对固定刷新节奏的反应——那是仿真伪影，不是执行智能。深度网络的真正增量在状态依赖：把冲击系数做成上一课那类条件函数后，最优切片随簿状态实时变形，这是线性二次闭式给不了的；但增量越大，对环境的依赖越深，验收越要按"),B("a",{href:"/quant/pomdp-fills"},"部分可观测"),a("的口径，把看不到的量——隐藏量、对手意图——排除出状态幻觉。")],-1)),E[5]||(E[5]=B("p",null,"「学出的策略随紧急度如何变形、以及怎么判它是执行智能还是仿真伪影」：",-1)),(A(),t(l,null,{default:e(()=>[i(n,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20U0%5B%22%E7%B4%A7%E6%80%A5%E5%BA%A6%E4%BD%8E%EF%BC%9A%E6%97%B6%E9%99%90%E5%AE%BD%E3%80%81%E4%BB%B7%E5%B7%AE%E8%B4%B5%22%5D%20--%3E%20U1%5B%22%E6%97%A0%E4%BA%A4%E6%98%93%E5%8C%BA%EF%BC%9A%E9%99%90%E4%BB%B7%E6%8C%82%E7%9D%80%E4%B8%8D%E5%8A%A8%22%5D%0A%20%20U1%20--%3E%20U2%5B%22%E7%B4%A7%E6%80%A5%E5%BA%A6%E4%B8%AD%EF%BC%9A%E9%99%90%E4%BB%B7%E4%B8%8E%E5%B8%82%E4%BB%B7%E5%88%87%E6%8D%A2%E5%B8%A6%E7%A7%BB%E5%8A%A8%22%5D%0A%20%20U2%20--%3E%20U3%5B%22%E7%B4%A7%E6%80%A5%E5%BA%A6%E9%AB%98%EF%BC%9A%E5%89%A9%E4%BD%99%E6%97%B6%E9%97%B4%E5%91%8A%E6%80%A5%22%5D%0A%20%20U3%20--%3E%20U4%5B%22%E4%B8%B4%E7%BB%88%E5%8A%A0%E9%80%9F%E6%B8%85%E7%AE%97%EF%BC%9A%E7%BB%88%E6%9C%9F%E6%B8%85%E9%9B%B6%E5%BA%93%E5%AD%98%E9%81%BF%E5%BC%80%E9%87%8D%E7%BD%9A%22%5D%0A%20%20U2%20--%3E%20CHK%7B%22%E7%AD%96%E7%95%A5%E5%8F%8D%E5%BA%94%E7%9A%84%E6%98%AF%E7%B0%BF%E7%8A%B6%E6%80%81%EF%BC%8C%E8%BF%98%E6%98%AF%E5%9B%9E%E6%94%BE%E5%99%A8%E7%9A%84%E5%9B%BA%E5%AE%9A%E5%88%B7%E6%96%B0%E8%8A%82%E5%A5%8F%EF%BC%9F%22%7D%0A%20%20CHK%20--%3E%7C%22%E7%B0%BF%E7%8A%B6%E6%80%81%22%7C%20OK%5B%22%E5%8F%AF%E8%A2%AB%E5%AD%98%E8%B4%A7%E9%80%BB%E8%BE%91%E8%A7%A3%E8%AF%BB%EF%BC%9A%E9%AA%8C%E6%94%B6%E9%80%9A%E8%BF%87%22%5D%0A%20%20CHK%20--%3E%7C%22%E5%9B%BA%E5%AE%9A%E8%8A%82%E5%A5%8F%22%7C%20BAD%5B%22%E4%BB%BF%E7%9C%9F%E4%BC%AA%E5%BD%B1%EF%BC%9A%E9%80%80%E5%9B%9E%E7%8E%AF%E5%A2%83%E7%99%BB%E8%AE%B0%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=r('<p><span class="marginnote">「实现短缺」代入数字：到达价 100.00 元，实际成交均价 100.05 元，短缺就是 5 个基点；若拖着不动、最后被迫以 100.20 元市价清仓，短缺变 20 个基点，还要叠加终期重罚——奖励函数就是用这组数字教策略「拖」有多贵。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>执行 RL 的合法目标是基准改进，不是在执行层找方向性 alpha——观点属于组合层，混进来会把评测污染成回测过拟合。做市是相邻问题：双侧报价、赚价差付逆向选择，状态与合法动作都不同，结论不可平移。延迟、限额与合规写成动作掩码与硬约束，不进奖励——「学合规」等于允许网络在训练分布里找绕开的路径。</p><p><span class="marginnote">「动作掩码」翻译一下：不是让网络学着不违规，而是在它输出动作之前，就把违规选项从菜单上物理划掉——好比拆掉遥控器上不许按的按键，而不是贴张纸条写「不许按」。合规不放进奖励的理由相同：奖励里留了例外，网络就会去搜例外。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>执行 RL 换掉的是线性二次假设；环境构造决定策略上限，模型假设从方程挪进仿真器。</li><li>状态含库存、时限与簿特征；奖励以到达价短缺加终期重罚，塑形项即问题定义。</li><li>环境三条路：历史回放、解析冲击、事件级仿真；简化登记，交付时随策略冻结。</li><li>对照协议：同数据同约束对 TWAP/VWAP/AC，报短缺分布；学出的结构要能被存货逻辑解读。</li><li>出处：Nevmyvaka, Feng and Kearns, <em>ICML</em>, 2006；Dabérius, Granat and Pakkanen, <em>Quantitative Finance</em>, 2020；Almgren and Chriss, 2000。</li></ul>',6))])}const q=s(p,[["render",F]]);export{c as __pageData,q as default};
